import { useState, useEffect } from "react";
import api from "../api";
import socket from "../socket";
import LiveMap from "../components/LiveMap";
import "./UserDashboard.css";

export default function UserDashboard() {
  const [services, setServices] = useState([]);
  const [bookings, setBookings] = useState([]);
  const [selectedService, setSelectedService] = useState(null);
  const [location, setLocation] = useState("");
  const [coordinates, setCoordinates] = useState(null);
  const [showPayment, setShowPayment] = useState(false);
  const [user, setUser] = useState(null);
  const [search, setSearch] = useState("");
  const [showQR, setShowQR] = useState(false);
  const [shareLiveLocation, setShareLiveLocation] = useState(false);
  const [locationStatus, setLocationStatus] = useState("");
  const [showMap, setShowMap] = useState(false);
  
  // Live tracking state
  const [activeBooking, setActiveBooking] = useState(null);
  const [providerLocation, setProviderLocation] = useState(null);
  const [trackingProviderId, setTrackingProviderId] = useState(null);

  useEffect(() => {
    const token = localStorage.getItem("token");
    if (token) {
      try {
        const decoded = JSON.parse(atob(token.split(".")[1]));
        setUser(decoded);
      } catch (err) {
        console.error("Error decoding token:", err);
      }
    }
    loadServices();
    loadBookings();
    socket.on("booking-update", () => {
      loadBookings();
    });
    return () => {
      socket.off("booking-update");
    };
  }, []);

  const loadServices = async () => {
    try {
      const response = await api.get("/services");
      setServices(response.data);
    } catch (err) {
      console.error("Error loading services:", err);
    }
  };

  const loadBookings = async () => {
    try {
      const response = await api.get("/bookings/my-bookings");
      setBookings(response.data);
    } catch (err) {
      console.error("Error loading bookings:", err);
    }
  };

  const handleBooking = (service) => {
    setSelectedService(service);
    setShowPayment(true);
  };

  const handlePaymentSuccess = async () => {
    try {
      const bookingData = {
        userId: user?.id,
        serviceName: selectedService.name,
        location: location,
        status: "pending",
        paymentStatus: "paid"
      };
      const response = await api.post("/bookings/book", bookingData);
      if (response.data === "Booking Created") {
        alert("Booking created successfully!");
        setShowPayment(false);
        setSelectedService(null);
        setLocation("");
        loadBookings();
      }
    } catch (err) {
      console.error("Error creating booking:", err);
      alert("Failed to create booking");
    }
  };

  const cancelBooking = async (bookingId) => {
    try {
      await api.post(`/bookings/status/${bookingId}`, { status: "cancelled" });
      loadBookings();
    } catch (err) {
      console.error("Error cancelling booking:", err);
    }
  };

  const getServiceIcon = (serviceName) => {
    const icons = {
      'Plumber': '🔧',
      'Electrician': '⚡',
      'AC Repair': '❄️',
      'Carpenter': '🪵',
      'House Cleaning': '🧹',
      'Painting': '🎨',
      'Pest Control': '🐛',
      'Gardening': '🌱',
      'Appliance Repair': '🔌',
      'Moving & Packing': '📦'
    };
    return icons[serviceName] || '🔧';
  };

  const filteredServices = services.filter(service => 
    service.name.toLowerCase().includes(search.toLowerCase()) ||
    service.category?.toLowerCase().includes(search.toLowerCase())
  );

  return (
    <div className="dashboard-container">

      {/* Header */}
      <header className="header">
        <h1 className="logo">FASTAID</h1>
        <div className="account-info">
          <span className="welcome-text">Welcome, {user?.name || 'User'} 👋</span>
          <button className="logout-btn" onClick={() => {
            localStorage.removeItem("token");
            window.location.href = "/";
          }}>
            Logout
          </button>
        </div>
      </header>

      {/* Hero Section */}
      <section className="hero">
        <h2>Find Trusted Services Near You</h2>
        <p>
          FASTAID connects you with verified professionals for health, home,
          vehicle, tech and more — quickly and securely.
        </p>

        {/* Trust Badges */}
        <div className="badges">
          <span className="badge">✔ Verified</span>
          <span className="badge">🔒 Secure</span>
          <span className="badge">⚡ Fast Service</span>
        </div>

        {/* Search Box */}
        <div className="search-container">
          <div className="search-box">
            <input
              type="text"
              placeholder="Search services like Plumber, Doctor..."
              value={search}
              onChange={(e) => setSearch(e.target.value)}
            />
            <button>Search</button>
          </div>
        </div>

        <button className="category-btn">
          View All Categories
        </button>
      </section>

      {/* Popular Services */}
      <section className="services-section">
        <h3 className="section-title">Popular Services</h3>

        <div className="services-grid">
          {filteredServices.length > 0 ? (
            filteredServices.map((service) => (
              <div key={service._id} className="service-card">
                <div className="service-icon" style={{ fontSize: '40px', marginBottom: '10px' }}>
                  {getServiceIcon(service.name)}
                </div>
                <h4>{service.name}</h4>
                <p className="rating">⭐ {service.rating || '4.5'}</p>
                <button onClick={() => handleBooking(service)}>Book</button>
              </div>
            ))
          ) : (
            <div className="empty-state" style={{ gridColumn: '1 / -1' }}>
              <div className="empty-state-icon">🔍</div>
              <h3>No services found</h3>
              <p>Try a different search term</p>
            </div>
          )}
        </div>
      </section>

      {/* My Bookings Section */}
      <section className="bookings-section">
        <h3 className="bookings-title">My Bookings</h3>

        {bookings.length === 0 ? (
          <div className="empty-state">
            <div className="empty-state-icon">📋</div>
            <h3>No bookings yet</h3>
            <p>Book a service to get started!</p>
          </div>
        ) : (
          <div className="services-grid">
            {bookings.map((booking) => (
              <div key={booking._id} className="booking-card">
                <div className="booking-info">
                  <h4>{booking.serviceName}</h4>
                  <p>📍 {booking.location}</p>
                  <p>💰 Payment: {booking.paymentStatus}</p>
                </div>
                <div className="booking-actions">
                  <span className={`status-badge status-${booking.status}`}>
                    {booking.status}
                  </span>
                  {booking.status === "pending" && (
                    <button 
                      onClick={() => cancelBooking(booking._id)}
                      className="cancel-btn"
                    >
                      Cancel
                    </button>
                  )}
                </div>
              </div>
            ))}
          </div>
        )}
      </section>

      {/* Payment Modal */}
      {showPayment && (
        <div className="payment-modal">
          <div className="payment-content">
            <h3>Booking: {selectedService?.name}</h3>
            
            {!showQR ? (
              <>
                <div className="form-group">
                  <label className="form-label">Location</label>
                  <input
                    type="text"
                    value={location}
                    onChange={(e) => setLocation(e.target.value)}
                    placeholder="Enter your location"
                  />
                </div>
                <div className="payment-buttons">
                  <button 
                    className="pay-btn" 
                    onClick={() => setShowQR(true)}
                    disabled={!location.trim()}
                  >
                    Pay Now
                  </button>
                  <button className="close-btn" onClick={() => {
                    setShowPayment(false);
                    setSelectedService(null);
                    setLocation("");
                    setShowQR(false);
                  }}>
                    Close
                  </button>
                </div>
              </>
            ) : (
              <>
                <div className="payment-qr">
                  <img 
                    src="/qr-code.png" 
                    alt="QR Code for Payment" 
                    style={{ 
                      maxWidth: '300px', 
                      width: '100%',
                      borderRadius: '8px',
                      border: '2px solid #f0f0f0'
                    }}
                    onError={(e) => {
                      e.target.style.display = 'none';
                      e.target.nextElementSibling.style.display = 'block';
                    }}
                  />
                  <div style={{ display: 'none', textAlign: 'center', padding: '20px' }}>
                    <p>QR Code not found. Please add qr-code.png to public folder.</p>
                  </div>
                </div>
                <p style={{ color: '#666', margin: '10px 0', textAlign: 'center' }}>
                  <strong>India Post UPI - 8339</strong><br/>
                  Scan the QR code with any UPI app to complete payment
                </p>
                <div className="payment-buttons">
                  <button 
                    className="pay-btn" 
                    onClick={handlePaymentSuccess}
                  >
                    ✓ Payment Done
                  </button>
                  <button className="close-btn" onClick={() => {
                    setShowQR(false);
                  }}>
                    Back
                  </button>
                </div>
              </>
            )}
          </div>
        </div>
      )}

    </div>
  );
}
